/**
 * Raises Gradle daemon memory for release builds (R8 + APK packaging exhaust
 * the RN template default of 2 GiB heap / 512 MiB metaspace).
 * Lives in a plugin because android/ is regenerated by `expo prebuild`.
 */
const { withGradleProperties, createRunOncePlugin } = require("expo/config-plugins");

const JVM_ARGS =
  "-Xmx4096m -XX:MaxMetaspaceSize=1536m -XX:+HeapDumpOnOutOfMemoryError -Dfile.encoding=UTF-8";

function setProperty(props, key, value) {
  const existing = props.find((item) => item.type === "property" && item.key === key);
  if (existing) {
    existing.value = value;
  } else {
    props.push({ type: "property", key, value });
  }
}

function withGradleJvmArgs(config) {
  return withGradleProperties(config, (mod) => {
    setProperty(mod.modResults, "org.gradle.jvmargs", JVM_ARGS);
    return mod;
  });
}

module.exports = createRunOncePlugin(withGradleJvmArgs, "with-gradle-jvm-args", "1.0.0");
